CREATE TABLE IF NOT EXISTS public.expense_reports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,merchant TEXT,expense_date DATE NOT NULL,category TEXT NOT NULL,amount NUMERIC(14,2) NOT NULL CHECK(amount>=0),currency_code CHAR(3) NOT NULL,receipt_key TEXT,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','approved','reimbursed','rejected')),policy_flags JSONB NOT NULL DEFAULT '[]'::jsonb,approved_by UUID REFERENCES public.users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());ALTER TABLE public.expense_reports ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON public.expense_reports FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));